<?php declare(strict_types=1);$reportValues=$reportUi['prepare_values'];$reportBlocked=$reportUi['blocked'];?>
<?php if($reportBlocked):?><section class="card"><p role="status"><?=e($reportText('Die Vorbereitung wurde nicht bestätigt. Deine Ergänzungen bleiben erhalten; prüfe zuerst, ob der Bericht bereits gespeichert wurde.'))?></p><a class="btn btn-outline theme-secondary" href="<?=e($reportUrl(['prepared_from'=>$reportValues['from_year'],'prepared_to'=>$reportValues['to_year']]))?>"><?=e($reportText('Gespeicherten Bericht für diesen Zeitraum prüfen'))?></a><label><?=e($reportText('Deine noch nicht gespeicherten Ergänzungen'))?><textarea class="form-control" rows="8" readonly data-activity-report-copy><?=(str_starts_with($reportValues['supplement'],"\n")||str_starts_with($reportValues['supplement'],"\r")?"\n":'').e($reportValues['supplement'])?></textarea></label></section><?php endif?>
<fieldset <?=$reportBlocked?'disabled':''?>><form method="post" action="<?=e($reportUrl())?>" class="card" data-activity-report-prepare <?=$reportBlocked?'data-activity-report-readonly':''?>><?=csrf().hidden('action','activity-report-prepare').hidden('report_kind',$reportKind).hidden('prepare_token',$reportValues['prepare_token'])?>
<h2><?=e($reportText($reportUi['posted']?'Berichtsvorbereitung':'Bericht aus Tätigkeiten vorbereiten'))?></h2><div class="report-fields"><label><?=e($reportText('Erstes Jahr'))?><input class="form-control" type="number" name="from_year" min="2000" max="<?=date('Y')?>" required value="<?=e($reportValues['from_year'])?>"></label><label><?=e($reportText('Letztes Jahr'))?><input class="form-control" type="number" name="to_year" min="2000" max="<?=date('Y')?>" required value="<?=e($reportValues['to_year'])?>"></label></div><p><?=e($reportText('Der Zeitraum umfasst höchstens drei aufeinanderfolgende Jahre.'))?></p><label><?=e($reportText('Ergänzungen des Vereins'))?><textarea class="form-control" name="supplement" rows="7" maxlength="40000"><?=(str_starts_with($reportValues['supplement'],"\n")||str_starts_with($reportValues['supplement'],"\r")?"\n":'').e($reportValues['supplement'])?></textarea></label><p><?=e($reportText('Der Bericht wird intern zur Prüfung vorbereitet. Eine Freigabe erfolgt erst nach der persönlichen PDF-Prüfung durch den 1. Vorstand.'))?></p><button class="btn btn-solid theme-primary"><?=e($reportText('Bericht aus Tätigkeiten vorbereiten'))?></button></form></fieldset>
